package fr.noxodev.noxoclaim;
import fr.noxodev.noxoclaim.commands.*; import fr.noxodev.noxoclaim.gui.ClaimGui; import fr.noxodev.noxoclaim.listeners.*; import fr.noxodev.noxoclaim.managers.*; import org.bukkit.plugin.java.JavaPlugin;
public final class NoxoClaim extends JavaPlugin { private ClaimManager claims; private SelectionManager selections; private MessageManager messages; public void onEnable(){saveDefaultConfig();saveResource("messages.yml",false);claims=new ClaimManager(getDataFolder());selections=new SelectionManager();messages=new MessageManager(getDataFolder());getServer().getPluginManager().registerEvents(new ClaimProtectionListener(this),this);getServer().getPluginManager().registerEvents(new WandListener(this),this);new ClaimGui(this);ClaimCommand c=new ClaimCommand(this);getCommand("claim").setExecutor(c);getCommand("claim").setTabCompleter(c);getCommand("claimadmin").setExecutor(new ClaimAdminCommand(this));getLogger().info("NoxoClaim activé.");}public void onDisable(){if(claims!=null)claims.save();}public ClaimManager claims(){return claims;}public SelectionManager selections(){return selections;}public MessageManager messages(){return messages;} }
